\draw[thick,rateblue] (0,2.1)--(0.7,2.1) .. controls (1.2,2.1) and (1.2,0.55) .. (2,0.55) .. controls (2.8,0.55) and (2.8,2.1) .. (3.3,2.1)--(3.9,2.1);
